static int[] TwoSum(int[] nums, int target)
{
    var seen = new Dictionary<int, int>();
    for (int i = 0; i < nums.Length; i++)
    {
        long need = (long)target - nums[i];
        if (need >= int.MinValue && need <= int.MaxValue &&
            seen.TryGetValue((int)need, out int j))
            return new[] { j, i };
        seen[nums[i]] = i;
    }
    return Array.Empty<int>();
}

var totals = orders
    .Where(o => o.Status == "Paid")
    .GroupBy(o => o.CustomerId)
    .Select(g => new {
        CustomerId = g.Key,
        Total = g.Sum(o => o.Amount)
    })
    .OrderByDescending(x => x.Total)
    .ToList();

public async Task<string> LoadAsync(
    HttpClient client, CancellationToken ct)
{
    using var response = await client.GetAsync(
        "https://example.com/api/catalog", ct);
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync(ct);
}

public interface IDiscount
{
    decimal Apply(decimal amount);
}
public sealed class TenPercent : IDiscount
{
    public decimal Apply(decimal amount) => amount * 0.90m;
}
public sealed class Checkout
{
    private readonly IDiscount discount;
    public Checkout(IDiscount discount) => this.discount = discount;
    public decimal Total(decimal amount) => discount.Apply(amount);
}
